scwin.trigger4_onclick = function(e) {
    dataList1.setColumnFilter({
        type: "row",
        colIndex: "col3",
        key: "4",
        condition: "<",
        columnDataType: "number"
    });
};
scwin.trigger5_onclick = function(e) {
    dataList1.setColumnFilter({
        type: "row",
        colIndex: "col2",
        key: "A",
        condition: "and"
    });
};
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].checked == true;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[13].checked == true;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[24].checked == true;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'setColumnFilter(col3)'버튼을 클릭한다.(4보다 작은값 필터링)
    //1. After running the sample, click the 'setColumnFilter (col3)' button (filtering less than 4)
    //Verify step 1. Values of 1, 2, and 3 less than 4 are filtered.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_0_2').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_2').text() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_2').text() == '3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 이후에 '금액'항목의 필터(역삼각형)를 클릭하여 FilterList의 전체 리스트가 보여지는지 확인한다.
    //2. Click on the filter (inverted triangle) in the 'Amount' field to see if the entire list of FilterList is visible.
    //Verify step 2. The FilterList is displayed as a whole list from 1 to 30. (Only the list of filtered 1,2,3 values is displayed before the function is added.)Filtering ignores sorting
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_header4_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_customFilter_list div').length == 32", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
